KEY_RIGHT equ 0x13
KEY_LEFT equ 0x11
BAT_RIGHT equ 0x59
BAT_LEFT equ 0x58
add_score:
  ldi b, 0x10
  st b, out
  ld b, score
  inc b
  st b, score
  st b, display
  ldi b, 0x80
  st b, out
  mov a, 0
  st a, display
key_read:
  ld b, in
  mov a, 0
  st a, in
  ldi a, KEY_RIGHT
  xor a, b
  jz bat_right
  ldi a, KEY_LEFT
  xor a, b
  jz bat_left
  jmp ball_clear
coord_to_pos:
  shl b
  shl b
  shl b
  shl b
  or a, b
  ldi c, 7
  and c, a
  ldi b, 0b10000000
  shr_loop:
    shr b
    dec c
    jns shr_loop
  rcl b
  shr a
  shr a
  shr a
  ldi c, 0x40
  add a, c
  jmp d
score db 255
speed_x db 1
speed_y db 0 - 1
ball_x db 0x07
ball_y db 0x0b
in db 0
out db 0x80
display db
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000001, 0b00000000,
0b00000011, 0b10000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000,
0b00000000, 0b00000000
bat_right:
  ldi b, BAT_RIGHT
  ld a, b
  shr a
  jc ball_move_x
  dec b
  ld a, b
  shr a
  st a, b
  inc b
  ld a, b
  rcr a
  st a, b
  jmp ball_clear
bat_left:
  ldi b, BAT_LEFT
  ld a, b
  shl a
  jc ball_clear
  inc b
  ld a, b
  shl a
  st a, b
  dec b
  ld a, b
  rcl a
  st a, b
ball_clear:
  ld a, ball_x
  ld b, ball_y
  ldi d, ball_move_x
  jmp coord_to_pos
ball_move_x:
  mov d, a
  mov a, b
  ld c, d
  xor c, a
  st c, d
  ld a, ball_x
check_left:
  or a, 0
  jnz check_right
  ldi b, 1
  st b, speed_x
  jmp add_x
check_right:
  ldi b, 0x0f
  xor b, a
  jnz add_x
  dec b
  st b, speed_x
add_x:
  ld c, speed_x
  add a, c
  st a, ball_x
ball_move_y:
  ld a, ball_y
check_up:
  or a, 0
  jnz check_down
  ldi b, 1
  st b, speed_y
  jmp add_y
check_down:
  ldi b, 0x0f
  xor b, a
  jz game_over
  ld c, speed_y
  inc c
  jz add_y
  inc a
  mov b, a
  ld a, ball_x
  ldi d, check_bat
  jmp coord_to_pos
check_bat:
  mov d, a
  mov a, b
  ld c, d
  and c, a
  jz return_a
  mov a, 0
  st a, draw_jmp + 1
  dec a
  st a, speed_y
return_a:
  ld a, ball_y
add_y:
  ld c, speed_y
  add a, c
  st a, ball_y
  mov b, a
  ld a, ball_x
  ldi d, draw
  jmp coord_to_pos
draw:
  mov d, a
  mov a, b
  ld c, d
  or c, a
  st c, d
draw_jmp:
  ldi d, key_read
  ldi a, key_read
  st a, draw_jmp + 1
  jmp d
game_over:
  ldi d, 0x40
  st d, out
  ldi c, game_over_text
text_loop:
  ld a, c
  st a, d
  inc c
  jnz text_loop
hlt
game_over_text db "GAME    OVER! "


